use builtin::{forall, exists};

/// Performs binary search on a non-empty, non-decreasing vector `v`
/// to find an index of the key `k`.  It is assumed that `k` does
/// appear at least once in `v`.
#[requires(v.len() > 0)]
#[requires(forall(|i: usize, j: usize| i < j && j < v.len() ==> v[i] <= v[j]))]
#[requires(exists(|i: usize| i < v.len() && v[i] == k))]
#[ensures(|res: usize| res < v.len())]
#[ensures(|res: usize| v[res] == k)]
pub fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = v.len() - 1;

    // Establish the loop invariants at the start.
    // 1) lo <= hi
    // 2) hi < v.len()
    // 3) k is known to lie somewhere in v[lo..=hi]
    assert(lo <= hi);
    assert(hi < v.len());
    assert(exists(|i: usize| lo <= i && i <= hi && v[i] == k));

    #[invariant(lo <= hi)]
    #[invariant(hi < v.len())]
    #[invariant(exists(|i: usize| lo <= i && i <= hi && v[i] == k))]
    #[decreases(hi - lo)]
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if v[mid] < k {
            // k must be in the right half
            lo = mid + 1;
        } else {
            // v[mid] >= k, so k is in the left half including mid
            hi = mid;
        }
    }

    // After the loop, lo == hi and by the invariant k must be at v[lo].
    assert(lo == hi);
    assert(v[lo] == k);

    lo
}

